package dev.raf.radar;
import android.content.*;import android.view.*;import android.widget.*;import androidx.test.core.app.ActivityScenario;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import static org.junit.Assert.*;import org.json.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;
public class PointHistoryUiTest {
 View text(View v,String value){if(v instanceof TextView&&value.contentEquals(((TextView)v).getText()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=text(((ViewGroup)v).getChildAt(i),value);if(found!=null)return found;}return null;}
 Point point(){Point p=new Point("history-fixture","Родник",55.178,61.308,false);p.address="Труда, 203 · Челябинск";return p;}
 void setup()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();Store s=new Store(c);s.prefs.edit().clear().putBoolean("autoUpdate",false).putBoolean("sounds",false).putBoolean("lineageSounds",false).putBoolean("experimentalStatistics",true).commit();AccountClient.save(s,new JSONObject().put("user",new JSONObject().put("id",999).put("name","Fixture")).put("session","a".repeat(64)));s.update(point());ScreenTest.grantAccess();AccountClient.transport=(b,t)->new JSONObject().put("friends",new JSONArray());Statistics.transport=(b,t)->{JSONArray accepted=new JSONArray(),meta=b.optJSONArray("sources"),ack=new JSONArray();if(meta!=null)for(int i=0;i<meta.length();i++)ack.put(new JSONObject().put("sourcePoint",meta.getJSONObject(i).getString("sourcePoint")).put("revision",meta.getJSONObject(i).getLong("revision")));return new JSONObject().put("accepted",accepted).put("acceptedSources",ack);};}
 @After public void cleanup(){AccountClient.transport=AccountClient::request;Statistics.transport=Statistics::request;PointStatistics.transport=PointStatistics::request;}
 @Test public void compactEditorBothThemesAndDraftCancelSave()throws Exception{setup();try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){
  AtomicReference<PointEditor> holder=new AtomicReference<>();for(String theme:new String[]{Appearance.STANDARD,Appearance.LINEAGE}){scenario.onActivity(a->{a.selectTheme(theme);PointEditor e=new PointEditor(a,point());holder.set(e);e.show();assertNotNull(text(e.dialog.getWindow().getDecorView(),"Сохранить"));assertEquals(View.GONE,e.controls.getVisibility());});ScreenTest.capture("point-editor-"+theme);scenario.onActivity(a->{PointEditor e=holder.get();e.name.setText("Не сохранять");e.draft.lat=56;text(e.dialog.getWindow().getDecorView(),"Отмена").performClick();Point saved=a.store.points().stream().filter(p->p.id.equals("history-fixture")).findFirst().get();assertEquals("Родник",saved.name);assertEquals(55.178,saved.lat,0);});}
  scenario.onActivity(a->{PointEditor e=new PointEditor(a,point());e.show();e.name.setText(" ");text(e.dialog.getWindow().getDecorView(),"Сохранить").performClick();assertTrue(e.dialog.isShowing());assertNotNull(e.name.getError());e.name.setText("Парковый");e.draft.lat=56;e.draft.address="Новое место";text(e.dialog.getWindow().getDecorView(),"Сохранить").performClick();Point saved=a.store.points().stream().filter(p->p.id.equals("history-fixture")).findFirst().get();assertEquals("Парковый",saved.name);assertEquals(56,saved.lat,0);assertFalse(e.dialog.isShowing());});}}
 JSONObject fixture(boolean empty)throws Exception{JSONArray slots=new JSONArray();for(int i=0;i<24;i++)slots.put(new JSONObject().put("hour",i).put("actual",empty||i>12?JSONObject.NULL:i==0?0:100).put("historical",empty?JSONObject.NULL:100+i*5).put("historyDays",empty?0:4).put("low",80).put("high",170));return new JSONObject().put("slots",slots).put("historyDays",empty?0:4).put("timezone","Asia/Yekaterinburg");}
 @Test public void pointCardHasStatisticsAndHourlyHistoryUsesBothThemes()throws Exception{setup();PointStatistics.transport=(q,t)->fixture(false);try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){for(String theme:new String[]{Appearance.STANDARD,Appearance.LINEAGE}){scenario.onActivity(a->{a.selectTheme(theme);a.edit(point());assertNotNull(text(a.pointSheet,"Статистика"));text(a.pointSheet,"Статистика").performClick();});ScreenTest.capture("point-history-"+theme);androidx.test.espresso.Espresso.onView(androidx.test.espresso.matcher.ViewMatchers.withText(org.hamcrest.Matchers.startsWith("История: 4 дня"))).check(androidx.test.espresso.assertion.ViewAssertions.matches(androidx.test.espresso.matcher.ViewMatchers.isDisplayed()));androidx.test.espresso.Espresso.onView(androidx.test.espresso.matcher.ViewMatchers.withContentDescription("Закрыть статистику точки")).perform(androidx.test.espresso.action.ViewActions.click());}}}
 @Test public void emptyAndFailedHistoryAreExplicitAndRetryWorks()throws Exception{setup();AtomicReference<PointStatistics> holder=new AtomicReference<>();PointStatistics.transport=(q,t)->{throw new java.io.IOException("fixture");};try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){scenario.onActivity(a->{PointStatistics p=new PointStatistics(a,point());holder.set(p);p.show();});ScreenTest.capture("point-history-error");scenario.onActivity(a->assertTrue(holder.get().status.getText().toString().contains("Не удалось")));PointStatistics.transport=(q,t)->fixture(true);scenario.onActivity(a->holder.get().retry.performClick());ScreenTest.capture("point-history-empty");JSONObject zero=new JSONObject().put("actual",0);scenario.onActivity(a->{assertTrue(holder.get().status.getText().toString().contains("пока нет"));assertEquals("0 ₽",PointStatistics.value(zero,"actual"));assertEquals("—",PointStatistics.value(new JSONObject(),"actual"));holder.get().dialog.dismiss();});}}
}
